// [S4] Three-portal family features — book appointment.
// Member picker: self always; Head can also book for minors (age < 18).
import 'package:family_veda/models/member.dart';
import 'package:family_veda/providers/active_member_provider.dart';
import 'package:family_veda/providers/family_dashboard_role_provider.dart';
import 'package:family_veda/providers/family_portal_provider.dart';
import 'package:family_veda/providers/members_provider.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

/// Returns the members an appointment can be booked for: always self,
/// plus minors (age < 18) when the current user is the Family Head.
List<Member> bookableMembers({
  required List<Member> allMembers,
  required String? activeMemberId,
  required bool isHead,
}) {
  final self = allMembers.where((m) => m.id == activeMemberId);
  if (!isHead) return self.toList(growable: false);

  bool isMinor(Member member) {
    final dob = member.dateOfBirth;
    if (dob == null) return false;
    final parsed = DateTime.tryParse(dob);
    if (parsed == null) return false;
    final now = DateTime.now();
    var age = now.year - parsed.year;
    if (now.month < parsed.month ||
        (now.month == parsed.month && now.day < parsed.day)) {
      age -= 1;
    }
    return age < 18;
  }

  final seen = <String>{};
  final result = <Member>[];
  for (final member in [...self, ...allMembers.where(isMinor)]) {
    if (seen.add(member.id)) result.add(member);
  }
  return result;
}

class BookAppointmentScreen extends ConsumerStatefulWidget {
  const BookAppointmentScreen({super.key});

  @override
  ConsumerState<BookAppointmentScreen> createState() =>
      _BookAppointmentScreenState();
}

class _BookAppointmentScreenState extends ConsumerState<BookAppointmentScreen> {
  final _reasonController = TextEditingController();
  String? _selectedMemberId;
  DateTime? _selectedDate;
  TimeOfDay? _selectedTime;
  final int _durationMinutes = 30;
  bool _submitting = false;

  @override
  void dispose() {
    _reasonController.dispose();
    super.dispose();
  }

  Future<void> _pickDateTime() async {
    final now = DateTime.now();
    final date = await showDatePicker(
      context: context,
      initialDate: now.add(const Duration(days: 1)),
      firstDate: now,
      lastDate: now.add(const Duration(days: 365)),
    );
    if (date == null || !mounted) return;
    final time = await showTimePicker(
      context: context,
      initialTime: TimeOfDay.fromDateTime(now.add(const Duration(hours: 1))),
    );
    if (time == null) return;
    setState(() {
      _selectedDate = date;
      _selectedTime = time;
    });
  }

  Future<void> _submit() async {
    final memberId = _selectedMemberId;
    final date = _selectedDate;
    final time = _selectedTime;
    final reason = _reasonController.text.trim();
    if (memberId == null || date == null || time == null || reason.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Fill in member, date/time and reason.')),
      );
      return;
    }
    final startsAt = DateTime(
      date.year,
      date.month,
      date.day,
      time.hour,
      time.minute,
    );
    setState(() => _submitting = true);
    try {
      await ref.read(familyPortalApiProvider).bookAppointment(
        memberId: memberId,
        startsAt: startsAt,
        durationMinutes: _durationMinutes,
        reason: reason,
      );
      ref.invalidate(myAppointmentsProvider);
      if (mounted) Navigator.of(context).pop(true);
    } on Object {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text(
              'Could not book the appointment. A family doctor must be assigned first.',
            ),
          ),
        );
      }
    } finally {
      if (mounted) setState(() => _submitting = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final activeMemberId = ref.watch(activeMemberProvider);
    final membersAsync = ref.watch(membersProvider);
    final isHead = ref.watch(isFamilyHeadProvider).valueOrNull ?? false;
    _selectedMemberId ??= activeMemberId;

    return Scaffold(
      appBar: AppBar(title: const Text('Book appointment')),
      body: SafeArea(
        child: membersAsync.when(
          loading: () => const Center(child: CircularProgressIndicator()),
          error: (_, _) => const Center(
            child: Text('Could not load family members. Try again.'),
          ),
          data: (allMembers) {
            final options = bookableMembers(
              allMembers: allMembers,
              activeMemberId: activeMemberId,
              isHead: isHead,
            );
            return ListView(
              padding: const EdgeInsets.all(16),
              children: [
                DropdownButtonFormField<String>(
                  initialValue: options.any((m) => m.id == _selectedMemberId)
                      ? _selectedMemberId
                      : (options.isEmpty ? null : options.first.id),
                  decoration: const InputDecoration(labelText: 'Who is this for?'),
                  items: options
                      .map(
                        (m) => DropdownMenuItem(
                          value: m.id,
                          child: Text(m.displayName),
                        ),
                      )
                      .toList(),
                  onChanged: (value) => setState(() => _selectedMemberId = value),
                ),
                const SizedBox(height: 16),
                ListTile(
                  contentPadding: EdgeInsets.zero,
                  title: Text(
                    _selectedDate == null || _selectedTime == null
                        ? 'Choose date and time'
                        : '${'${_selectedDate!.toLocal()}'.split(' ').first} '
                              '${_selectedTime!.format(context)}',
                  ),
                  trailing: const Icon(Icons.calendar_today_outlined),
                  onTap: _pickDateTime,
                ),
                const SizedBox(height: 8),
                TextField(
                  controller: _reasonController,
                  maxLength: 200,
                  decoration: const InputDecoration(
                    labelText: 'Reason for visit',
                  ),
                ),
                const SizedBox(height: 16),
                ElevatedButton(
                  onPressed: _submitting ? null : _submit,
                  child: _submitting
                      ? const SizedBox(
                          width: 20,
                          height: 20,
                          child: CircularProgressIndicator(strokeWidth: 2),
                        )
                      : const Text('Request appointment'),
                ),
              ],
            );
          },
        ),
      ),
    );
  }
}
